/**
 * Redirects for URLs that no longer exist on docs.uavmatrix.com.
 *
 * GitHub Pages cannot send server-side 301s, so these are generated by
 * @docusaurus/plugin-client-redirects as small HTML pages with a meta refresh
 * and a canonical link to the target. Search engines treat an instant meta
 * refresh much like a permanent redirect.
 *
 * Every target must be a real page and no source may be a real page. The
 * build fails if either rule is broken (see redirectChecksPlugin in
 * docusaurus.config.ts).
 *
 * Sources:
 * - The old MkDocs site (2019 to Nov 2024), recovered from the gh-pages
 *   branch history and the Wayback Machine. It was served at the root and
 *   under version folders such as /4.x/, /5.x/, /latest/.
 * - Links that installed copies of UAVcast-Pro and the store use and that
 *   cannot be updated in the field (/licensing, /installation/).
 * - Docusaurus-era URLs that are gone.
 */

export const SITE_URL = "https://docs.uavmatrix.com";

const V6 = "/docs/6.x";

/** Current 6.x pages, with the trailing slash that GitHub Pages serves. */
const page = {
	introduction: `${V6}/introduction/`,
	installation: `${V6}/installation/`,
	hardware: `${V6}/hardware/`,
	license: `${V6}/get_started/license/`,
	quickStart: `${V6}/quick-start/`,
	dashboard: `${V6}/configuration-dashboard/`,
	flightController: `${V6}/configuration-flight-controller/`,
	groundControl: `${V6}/configuration-ground-controller/`,
	map: `${V6}/configuration-map/`,
	camera: `${V6}/configuration-camera/`,
	cellModem: `${V6}/configuration-cell-modem/`,
	vpn: `${V6}/configuration-vpn/`,
	dynamicDns: `${V6}/configuration-dynamic-dns/`,
	networks: `${V6}/configuration-networks/`,
	settings: `${V6}/configuration-settings/`,
	injectors: `${V6}/configuration-injectors/`,
	contributors: `${V6}/configuration-contributors/`,
	libraries: `${V6}/configuration-libraries/`,
	faq: `${V6}/frequently-asked-questions/`,
	changelog: `${V6}/changelog/`,
} as const;

/**
 * Pages of the old MkDocs site, relative to the site root or to one of
 * legacyPrefixes. Mixed-case paths also get an all-lowercase variant,
 * because GitHub Pages paths are case-sensitive.
 */
const legacyPages: Record<string, string> = {
	"installation": page.installation,
	"application-update": page.settings,
	"hardware": page.hardware,
	"how_it_works": page.introduction,
	"license/license": page.license,
	"libraries": page.libraries,
	"changelog": page.changelog,
	"troubleshooting": page.faq,
	"pages/Dashboard": page.dashboard,
	"pages/Application": page.settings,
	"pages/Flight-Controller": page.flightController,
	"pages/Ground-Control": page.groundControl,
	"pages/Map": page.map,
	"pages/Cockpit": page.map,
	"pages/Camera": page.camera,
	"pages/camera/Configuration": page.camera,
	"pages/Cell-Modem": page.cellModem,
	"pages/Vpn": page.vpn,
	"pages/Dynamic-DNS": page.dynamicDns,
	"pages/raspberry/diagnostic": page.dashboard,
	"pages/raspberry/led": page.dashboard,
	"pages/raspberry/network": page.networks,
	"pages/beta": page.changelog,
	"pages/developer": page.changelog,
	"vpn/zerotier": page.vpn,
	"developers/restapi": page.injectors,
	"developers/translation": page.contributors,
};

/** Version folders the old site was served under ("" is the site root). */
const legacyPrefixes = ["", "/4.x", "/4x", "/5.x", "/5", "/latest", "/site"];

/** Other dead URLs. */
const otherRedirects: Record<string, string> = {
	// Linked from the UAVcast-Pro license page and branding config in the field.
	"/licensing/": page.license,
	"/license/": page.license,
	// Bare docs and version roots have never had a page.
	"/docs/": page.introduction,
	"/docs/6.x/": page.introduction,
	"/docs/5.x/": page.introduction,
	"/docs/4.x/": page.introduction,
	// Removed on 2026-11-23 until Fleet Connect ships. Delete this line when
	// the page comes back, or the build will fail on the collision.
	"/docs/6.x/configuration-fleet-connect/": page.introduction,
	// Docusaurus template page, removed.
	"/markdown-page/": "/",
};

/**
 * Old paths that contain spaces. PathnameSchema in the redirect plugin rejects
 * them, so redirectChecksPlugin writes these pages itself.
 */
const legacyPagesWithSpaces: Record<string, string> = {
	"pages/camera/HTTP Videostream": page.camera,
};

export type Redirect = { from: string; to: string };

function withLowercase(paths: Record<string, string>): [string, string][] {
	const out = new Map<string, string>();
	for (const [from, to] of Object.entries(paths)) {
		out.set(from, to);
		out.set(from.toLowerCase(), to);
	}
	return [...out.entries()];
}

function expandLegacy(paths: Record<string, string>): Redirect[] {
	const out: Redirect[] = [];
	for (const prefix of legacyPrefixes) {
		for (const [path, to] of withLowercase(paths)) {
			out.push({ from: `${prefix}/${path}/`, to });
		}
		if (prefix) out.push({ from: `${prefix}/`, to: page.introduction });
	}
	return out;
}

const absolute = (r: Redirect): Redirect => ({ from: r.from, to: `${SITE_URL}${r.to}` });

/** Redirects handled by @docusaurus/plugin-client-redirects. */
export const redirects: Redirect[] = [
	...expandLegacy(legacyPages),
	...Object.entries(otherRedirects).map(([from, to]) => ({ from, to })),
].map(absolute);

/** Redirects written by redirectChecksPlugin (paths with spaces). */
export const rawRedirects: Redirect[] = expandLegacy(legacyPagesWithSpaces)
	.filter((r) => r.from.includes(" "))
	.map(absolute);
